timeScope:
let WindowEnd = min_of(datetime({TimeRange:end}), now());
let WindowStart = max_of(datetime({TimeRange:start}), WindowEnd - 90d, ago(90d));
let TimeEvents = AppEvents
| where TimeGenerated >= WindowStart and TimeGenerated <= WindowEnd
| where tostring(Properties.schemaVersion) == '2';

filterScope:
let Events = TimeEvents
| where ('{Version:escape}' == '*' or tostring(Properties.extensionVersion) == '{Version:escape}')
    and ('{Host:escape}' == '*' or tostring(Properties.host) == '{Host:escape}');
let UsageEvents = Events | where Name != 'sysml.error';
let CorrelatedUsage = UsageEvents | where isnotempty(UserId) and isnotempty(SessionId) and tolong(Measurements.sequence) > 0;
let FeatureEvents = CorrelatedUsage
| where Name != 'sysml.language.operation'
| where Name == 'sysml.panel.opened' or Name endswith '.operation'
| extend Sequence = tolong(Measurements.sequence),
    Feature = iif(Name == 'sysml.panel.opened', strcat('panel:', tostring(Properties.panel)),
      strcat(Name, ':', tostring(Properties.action), iif(isempty(tostring(Properties.view)), '', strcat(':', tostring(Properties.view)))));

queries.query:
let AllInstallations = toscalar(CorrelatedUsage | summarize Total = dcount(UserId, 2));
let AllSessions = toscalar(CorrelatedUsage | summarize Total = dcount(SessionId, 2));
FeatureEvents
| summarize FeatureRecords = count(), Installations = dcount(UserId, 2), Sessions = dcount(SessionId, 2) by Feature
| extend InstallationReachPct = iif(AllInstallations == 0, real(null), 100.0 * Installations / AllInstallations), SessionReachPct = iif(AllSessions == 0, real(null), 100.0 * Sessions / AllSessions), RecordsPerReachedInstallation = 1.0 * FeatureRecords / Installations
| order by FeatureRecords desc
